"""Weekly timesheet lines built from a list of shifts."""

from collections import defaultdict
from typing import Dict, Iterable, List, Tuple

from hourglass.models import Shift

MINUTES_PER_HOUR = 60


def _check(shifts: List[Shift]) -> None:
    if not shifts:
        raise ValueError("no shifts to total")
    for shift in shifts:
        if not shift.worker.strip():
            raise ValueError("shift has a blank worker name")


def _tally(shifts: List[Shift]) -> Dict[str, List[int]]:
    totals = defaultdict(lambda: [0, 0])
    for shift in shifts:
        entry = totals[shift.worker]
        entry[0] += 1
        entry[1] += shift.span.minutes
    return totals


def _busiest(item: Tuple[str, List[int]]) -> tuple:
    name, (count, minutes) = item
    return (-minutes, -count, name)


def _render(totals: Dict[str, List[int]]) -> List[str]:
    lines = []
    for name, (count, minutes) in sorted(totals.items(), key=_busiest):
        hours = minutes / MINUTES_PER_HOUR
        lines.append(f"{name}  shifts={count}  hours={hours:.1f}")
    return lines


def weekly_timesheet(shifts: Iterable[Shift]) -> List[str]:
    """One line per worker, busiest first. ValueError on bad input."""
    listed = list(shifts)
    _check(listed)
    return _render(_tally(listed))
