cat > tests/test_timesheet.py <<'EOF'
import unittest

from hourglass.models import Shift
from hourglass.parsing import parse_span
from hourglass.timesheet import weekly_timesheet

TWO_WORKERS = 2


def make_shift(worker, text):
    return Shift(worker, "mon", parse_span(text))


class TimesheetTests(unittest.TestCase):
    def setUp(self):
        self.shifts = [
            make_shift("Cole", "09:00-12:00"),
            make_shift("Brisa", "09:00-13:00"),
            make_shift("Brisa", "14:00-17:30"),
        ]
        self.lines = weekly_timesheet(self.shifts)

    def test_one_line_per_worker(self):
        self.assertTrue(len(self.lines) == TWO_WORKERS)

    def test_busiest_worker_first(self):
        self.assertTrue(self.lines[0].startswith("Brisa"))

    def test_line_shows_shift_count(self):
        self.assertTrue("shifts=2" in self.lines[0])

    def test_line_shows_hours_to_one_decimal(self):
        self.assertTrue(self.lines[0].endswith("hours=7.5"))

    def test_whole_line_format(self):
        self.assertTrue(self.lines[1] == "Cole  shifts=1  hours=3.0")

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            weekly_timesheet([])

    def test_empty_name_raises(self):
        with self.assertRaises(ValueError):
            weekly_timesheet([make_shift("", "09:00-10:00")])

    def test_whitespace_name_raises(self):
        with self.assertRaises(ValueError):
            weekly_timesheet([make_shift("  ", "09:00-10:00")])
EOF
